34	
35	/** Keeps the people's claims on each sheet. A claim with no date is dated the sheet's today. */
36	@Service
37	public class ClaimService {
38	
39	    private final ClaimRepository claims;
40	    private final PersonRepository people;
41	    private final RateRepository rates;
42	    private final SheetService sheets;
43	    private final SheetRepository sheetRows;
44	    private final PeriodRepository periods;
45	    private final StatementRepository statements;
46	    private final Rollup rollup;
47	    private final RoleService roles;
48	    private final Audit audit;
49	
50	    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates, SheetService sheets,
51	            SheetRepository sheetRows, PeriodRepository periods, StatementRepository statements, Rollup rollup,
52	            RoleService roles, Audit audit) {
53	        this.roles = roles;
54	        this.sheetRows = sheetRows;
55	        this.periods = periods;
56	        this.rollup = rollup;
57	        this.claims = claims;
58	        this.people = people;
59	        this.rates = rates;
60	        this.sheets = sheets;
61	        this.statements = statements;
62	        this.audit = audit;
63	    }
64	
65	    /** The sheet's claims, newest first. */
66	    @Transactional(readOnly = true)
67	    public List<Claim> list(String sheetId) {
68	        sheets.today(sheetId);
69	        return claims.findBySheetIdOrderByListOrderDesc(sheetId);
70	    }
71	
72	    /** Add a claim; a negative amount (a correction) must name a SETTLED claim of the person by number,
73	     *  and a claim of 0.00 or more must name none. */
74	    @Transactional
75	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
76	            String corrects) {
77	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
78	        LocalDate on = date != null ? date : sheets.today(sheetId);
79	        refuseClosed(sheetId, on);
80	        refuseRetired(person, on);
81	        refuseCorrection(sheetId, personId, amount, corrects);
82	        Rollup.Snapshot before = rollup.take(sheetId);
83	        int terms = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
84	                .termsFor(person.gradeOn(on), on);
85	        Claim claim = new Claim(sheetId, personId, amount.setScale(2), on, on.plusDays(terms), note, corrects);
86	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
87	        logStatus(claim, person, user);
88	        claim = claims.saveAndFlush(claim);
89	        audit("CLAIM_ADDED", claim, person, user);
90	        rollup.recordChanges(sheetId, user, before);
91	        return claim;
92	    }
93	
94	    /** Change a DRAFT claim; a claim in any other status is refused, and a correction as when added. */
95	    @Transactional
96	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
97	            String corrects) {
98	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
99	        if (claim.getStatus() != ClaimStatus.DRAFT) {
100	            throw new ClaimNotDraftException(claim.getStatus());
101	        }
102	        LocalDate on = date != null ? date : sheets.today(sheetId);
103	        refuseClosed(sheetId, claim.getDate());
104	        refuseClosed(sheetId, on);
105	        refuseRetired(people.findByIdAndSheetId(claim.getPersonId(), sheetId)
106	                .orElseThrow(PersonNotFoundException::new), on);
107	        refuseCorrection(sheetId, claim.getPersonId(), amount, corrects);
108	        Rollup.Snapshot before = rollup.take(sheetId);
109	        claim.setAmount(amount.setScale(2));
110	        claim.setDate(on);
111	        claim.setNote(note);
112	        claim.setCorrects(corrects);
113	        Claim updated = claims.saveAndFlush(claim);
114	        Person person = people.findByIdAndSheetId(updated.getPersonId(), sheetId)
115	                .orElseThrow(PersonNotFoundException::new);
116	        audit("CLAIM_EDITED", updated, person, user);
117	        rollup.recordChanges(sheetId, user, before);
118	        return updated;
119	    }
120	
121	    /** Move a claim to another status; refused when the user's role may not open, settle or void it (the
122	     *  sheet's permission matrix), when its current status does not allow it,
123	     *  or when the user settling it is the one who opened it. A clerk settling a claim whose due is above
124	     *  the sheet's clerk limit (a due of n/a is within any limit) puts it PENDING instead, for a steward to
125	     *  approve or reject; its due stays live. Settling fixes the
126	     *  claim's due at its grade's rate in force on its date (a claim bound by a statement at the figure it
127	     *  bound), its late charge on the sheet's today frozen in on top; with no figure then, its due stays live. */
128	    @Transactional
129	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
130	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
131	        refuseClosed(sheetId, claim.getDate());
132	        roles.require(sheetId, user, switch (to) {
133	            case OPEN -> "open";
134	            case SETTLED, PENDING -> "settle";
135	            case VOID -> "void";
136	            case DRAFT -> throw new IllegalStateException();
137	        });
138	        if (!claim.getStatus().canBecome(to)) {
139	            throw new ClaimStatusException(claim.getStatus(), to);
140	        }
141	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
142	            throw new ClaimSettlerException();
143	        }
144	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
145	            throw new ClaimDeferException("The claim is deferred until " + claim.getDeferredUntil() + ".");
146	        }
147	        Rollup.Snapshot before = rollup.take(sheetId);
148	        String number = claim.getNumber();
149	        if (to == ClaimStatus.OPEN) {
150	            number = sheets.nextClaimNumber(sheetId, claim.getDate());
151	            claim.setOpenedBy(user);
152	        }
153	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
154	                .orElseThrow(PersonNotFoundException::new);
155	        if (to == ClaimStatus.SETTLED) {
156	            BigDecimal figure = claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
157	            BigDecimal due = figure == null ? null : charged(claim, figure);
158	            refuseUnproved(claim, due);
159	            if (overLimit(sheetId, user, due)) {
160	                to = ClaimStatus.PENDING;
161	            } else {
162	                claim.setSettledDue(due);
163	            }
164	        }
165	        claim.setStatus(to);
166	        claim.setNumber(number);
167	        logStatus(claim, person, user);
168	        Claim updated = claims.saveAndFlush(claim);
169	        String event = switch (to) {
170	            case OPEN -> "CLAIM_OPENED";
171	            case PENDING -> "CLAIM_PENDING";
172	            case SETTLED -> "CLAIM_SETTLED";
173	            case VOID -> "CLAIM_VOIDED";
174	            case DRAFT -> throw new IllegalStateException();
175	        };
176	        audit(event, updated, person, user, number, to == ClaimStatus.SETTLED ? dueField(updated) : "");
177	        rollup.recordChanges(sheetId, user, before);
178	        return updated;
179	    }
180	
181	    /** Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure now, its late charge on
182	     *  the sheet's today frozen in on top (with no figure then, its due stays live). Refused unless the
183	     *  claim is PENDING and the user is a steward other than the one who opened it. */
184	    @Transactional
185	    public Claim approve(String sheetId, String user, long claimId) {
186	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
187	        refuseClosed(sheetId, claim.getDate());
188	        if (claim.getStatus() != ClaimStatus.PENDING) {
189	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
190	        }
191	        if (!roles.isSteward(sheetId, user)) {
192	            throw new ClaimApprovalException("Only a steward can approve a claim.");
193	        }
194	        if (user.equals(claim.getOpenedBy())) {
195	            throw new ClaimApprovalException("The user who opened a claim cannot approve it.");
196	        }
197	        Rollup.Snapshot before = rollup.take(sheetId);
198	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
199	                .orElseThrow(PersonNotFoundException::new);
200	        BigDecimal figure = liveDue(claim, person);
201	        BigDecimal due = figure == null ? null : charged(claim, figure);
202	        refuseUnproved(claim, due);
203	        claim.setSettledDue(due);
204	        claim.setStatus(ClaimStatus.SETTLED);
205	        logStatus(claim, person, user);
206	        Claim updated = claims.saveAndFlush(claim);
207	        audit("CLAIM_APPROVED", updated, person, user, updated.getNumber(), dueField(updated));
208	        rollup.recordChanges(sheetId, user, before);
209	        return updated;
210	    }
211	
212	    /** Raise a claim's proofs count by one. Refused for a SETTLED or VOID claim, and a claim in a closed
213	     *  period. */
214	    @Transactional
215	    public Claim addProof(String sheetId, String user, long claimId) {
216	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
217	        refuseClosed(sheetId, claim.getDate());
218	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
219	            throw new ClaimProofException("A " + claim.getStatus() + " claim takes no proof.");
220	        }
221	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
222	                .orElseThrow(PersonNotFoundException::new);
223	        claim.addProof();
224	        Claim updated = claims.saveAndFlush(claim);
225	        audit("CLAIM_PROOF_ADDED", updated, person, user, updated.getNumber(), " proofs=" + updated.getProofs());
226	        return updated;
227	    }
228	
229	    /** Re-settle a SETTLED claim: freeze it again at the figure it would have today as an OPEN claim bound by
230	     *  no statement (today's rates, grades and floor, the late charge on the sheet's today on top). Refused
231	     *  unless the claim is SETTLED and the user is a steward, and for a claim in a closed period. */
232	    @Transactional
233	    public Claim resettle(String sheetId, String user, long claimId) {
234	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
235	        refuseClosed(sheetId, claim.getDate());
236	        if (!roles.isSteward(sheetId, user)) {
237	            throw new ClaimResettleException("Only a steward can re-settle a claim.");
238	        }
239	        if (claim.getStatus() != ClaimStatus.SETTLED) {
240	            throw new ClaimResettleException("Only a SETTLED claim can be re-settled.");
241	        }
242	        Rollup.Snapshot before = rollup.take(sheetId);
243	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
244	                .orElseThrow(PersonNotFoundException::new);
245	        BigDecimal old = claim.getSettledDue();
246	        BigDecimal figure = liveDue(claim, person);
247	        BigDecimal due = figure == null || claim.isCorrection() ? figure
248	                : figure.add(sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
249	                        .lateCharge(figure, claim.getDueBy(), claim.getDate()));
250	        claim.setSettledDue(due);
251	        logStatus(claim, person, user);
252	        Claim updated = claims.saveAndFlush(claim);
253	        audit("CLAIM_RESETTLED", updated, person, user, updated.getNumber(),
254	                " old=" + show(old) + " new=" + show(due));
255	        rollup.recordChanges(sheetId, user, before);
256	        return updated;
257	    }
258	
259	    /** Reject a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last
260	     *  statement if that statement included it. Refused unless the claim is PENDING, the user is a
261	     *  steward and a reason is given. */
262	    @Transactional
263	    public Claim reject(String sheetId, String user, long claimId, String reason) {
264	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
265	        refuseClosed(sheetId, claim.getDate());
266	        if (claim.getStatus() != ClaimStatus.PENDING) {
267	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.OPEN);
268	        }
269	        if (!roles.isSteward(sheetId, user)) {
270	            throw new ClaimApprovalException("Only a steward can reject a claim.");
271	        }
272	        if (reason.isEmpty()) {
273	            throw new ClaimApprovalException("Give a reason to reject the claim.");
274	        }
275	        Rollup.Snapshot before = rollup.take(sheetId);
276	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
277	                .orElseThrow(PersonNotFoundException::new);
278	        claim.setStatus(ClaimStatus.OPEN);
279	        logStatus(claim, person, user);
280	        Claim updated = claims.saveAndFlush(claim);
281	        audit("CLAIM_REJECTED", updated, person, user, updated.getNumber(), " reason=" + reason);
282	        rollup.recordChanges(sheetId, user, before);
283	        return updated;
284	    }
285	
286	    /** Defer an OPEN claim to a date after the sheet's today: until the sheet's today reaches it, the claim
287	     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for
288	     *  a claim that is not OPEN, a date not after the sheet's today, and a claim in a closed period. */
289	    @Transactional
290	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
291	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
292	        refuseClosed(sheetId, claim.getDate());
293	        if (claim.getStatus() != ClaimStatus.OPEN) {
294	            throw new ClaimDeferException("Only an OPEN claim can be deferred.");
295	        }
296	        if (until == null || !until.isAfter(sheets.today(sheetId))) {
297	            throw new ClaimDeferException("Defer the claim to a date after the sheet's today.");
298	        }
299	        Rollup.Snapshot before = rollup.take(sheetId);
300	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
301	                .orElseThrow(PersonNotFoundException::new);
302	        claim.setDeferredUntil(until);
303	        Claim updated = claims.saveAndFlush(claim);
304	        audit("CLAIM_DEFERRED", updated, person, user, updated.getNumber(), " until=" + until);
305	        rollup.recordChanges(sheetId, user, before);
306	        return updated;
307	    }
308	
309	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
310	     *  loses any figure a statement bound it to (live again until its new person's next statement), and is
311	     *  listed as its new person's newest claim. Refused unless the user's role may reassign, and for a settled or
312	     *  voided claim, a claim in a closed period, the claim's own person, or a person retired on its date. */
313	    @Transactional
314	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
315	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
316	        refuseClosed(sheetId, claim.getDate());
317	        if (!roles.allows(sheetId, user, "reassign")) {
318	            throw new ClaimReassignException("Your role may not reassign a claim.");
319	        }
320	        if (!claim.getStatus().canMove()) {
321	            throw new ClaimReassignException("A " + claim.getStatus() + " claim cannot be reassigned.");
322	        }
323	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
324	                .orElseThrow(PersonNotFoundException::new);
325	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
326	        if (from.getId().equals(to.getId())) {
327	            throw new ClaimReassignException("The claim is already " + to.getName() + "'s.");
328	        }
329	        refuseRetired(to, claim.getDate());
330	        Rollup.Snapshot before = rollup.take(sheetId);
331	        claim.setPersonId(to.getId());
332	        claim.setStated(false, null);
333	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
334	        Claim updated = claims.saveAndFlush(claim);
335	        audit("CLAIM_REASSIGNED", updated, to, user, updated.getNumber(),
336	                " from=" + from.getName() + " to=" + to.getName());
337	        rollup.recordChanges(sheetId, user, before);
338	        return updated;
339	    }
340	
341	    /** What a bulk open did: how many it opened and refused, and the claims it opened. */
342	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
343	    }
344	
345	    /** Open the chosen claims together, numbering them in list order (people in the order they were added,
346	     *  each person's claims newest first); a claim that cannot be opened is left as it is and counted as
347	     *  refused, as is one not on the sheet. */
348	    @Transactional
349	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
350	        Set<Long> chosen = new HashSet<>(claimIds);
351	        if (roles.isViewer(sheetId, user)) {
352	            return new BulkOpened(0, chosen.size(), List.of());
353	        }
354	        List<Claim> opened = new ArrayList<>();
355	        for (Claim claim : inListOrder(sheetId, chosen)) {
356	            try {
357	                opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
358	            } catch (ClaimStatusException | PeriodClosedException | ClaimNotFoundException
359	                    | ActionNotAllowedException e) {
360	                // refused: left as it is
361	            }
362	        }
363	        return new BulkOpened(opened.size(), chosen.size() - opened.size(), opened);
364	    }
365	
366	    /** What a bulk settle did: how many it settled (PENDING included) and refused, and the claims it changed. */
367	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
368	    }
369	
370	    /** Settle the chosen claims together in list order (people in the order they were added, each person's
371	     *  claims newest first), each as a single settle by the user would: one a clerk puts PENDING counts as
372	     *  settled, and one that cannot be settled is left as it is and counted as refused, as is one not on
373	     *  the sheet. */
374	    @Transactional
375	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> claimIds) {
376	        Set<Long> chosen = new HashSet<>(claimIds);
377	        if (roles.isViewer(sheetId, user)) {
378	            return new BulkSettled(0, chosen.size(), List.of());
379	        }
380	        List<Claim> settled = new ArrayList<>();
381	        for (Claim claim : inListOrder(sheetId, chosen)) {
382	            try {
383	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
384	            } catch (ClaimStatusException | ClaimSettlerException | ClaimDeferException | ClaimProofException
385	                    | PeriodClosedException | ActionNotAllowedException
386	                    | ClaimNotFoundException e) {
387	                // refused: left as it is
388	            }
389	        }
390	        return new BulkSettled(settled.size(), chosen.size() - settled.size(), settled);
391	    }
392	
393	    /** The sheet's chosen claims in list order: people in the order they were added, each person's claims
394	     *  newest first. */
395	    private List<Claim> inListOrder(String sheetId, Set<Long> chosen) {
396	        Map<Long, Integer> personOrder = new HashMap<>();
397	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
398	            personOrder.put(person.getId(), personOrder.size());
399	        }
400	        return claims.findBySheetIdOrderByListOrderDesc(sheetId).stream()
401	                .filter(c -> chosen.contains(c.getId()))
402	                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
403	                .toList();
404	    }
405	
406	    /** A person, their statements in the order taken, and their claims newest first. */
407	    public record Stated(Person person, List<Statement> statements, List<Claim> claims) {
408	    }
409	
410	    /** Take a person's statement: record their due-total now (late charges included) and how many claims
411	     *  count, and bind each claim that counts to the figure it has now, under its late charge (the charge is
412	     *  never bound: it keeps following the sheet's today; a PENDING claim is bound only once it is back to
413	     *  OPEN); a claim that does not count, is OPEN or PENDING and dated within one of its person's holds, or is
414	     *  deferred past the sheet's today, is left unbound. */
415	    @Transactional
416	    public Stated statement(String sheetId, String user, long personId) {
417	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
418	        LocalDate today = sheets.today(sheetId);
419	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
420	        Rollup.Snapshot before = rollup.take(sheetId);
421	        BigDecimal total = BigDecimal.ZERO.setScale(2);
422	        boolean figure = false;
423	        int counted = 0;
424	        for (Claim claim : theirs) {
425	            if (!claim.getStatus().counts() || (claim.getStatus().isOpen() && person.heldOn(claim.getDate()))
426	                    || claim.deferredOn(today)) {
427	                claim.setStated(false, null);
428	                continue;
429	            }
430	            BigDecimal due = due(claim, person);
431	            if (due != null) {
432	                total = total.add(charged(claim, due));
433	                figure = true;
434	            }
435	            claim.setStated(true, due);
436	            counted++;
437	        }
438	        boolean rated = rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
439	        BigDecimal summed = total;
440	        BigDecimal dueTotal = rated || figure
441	                ? sheetRows.findById(sheetId).map(s -> s.capped(summed)).orElse(summed) : null;
442	        claims.saveAllAndFlush(theirs);
443	        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
444	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
445	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
446	        rollup.recordChanges(sheetId, user, before);
447	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
448	    }
449	
450	    /** Refuse a change to a claim dated inside a closed period. Locks the sheet first, so a period being
451	     *  closed at the same moment is seen. */
452	    private void refuseClosed(String sheetId, LocalDate date) {
453	        sheetRows.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
454	        if (periods.closedOn(sheetId, date)) {
455	            throw new PeriodClosedException();
456	        }
457	    }
458	
459	    /** Refuse settling or approving a claim with no proof whose due is above the proof threshold in force on
460	     *  its date; a due of n/a, or no threshold then, needs none. */
461	    private void refuseUnproved(Claim claim, BigDecimal due) {
462	        BigDecimal threshold = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new)
463	                .proofThresholdOn(claim.getDate());
464	        if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
465	            throw new ClaimProofException("The claim's due is above the proof threshold: add a proof first.");
466	        }
467	    }
468	
469	    /** Whether a clerk is settling a due above the sheet's clerk limit; a steward settles anything, and a
470	     *  due of n/a, or a sheet with no limit, is within it. */
471	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
472	        BigDecimal limit = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new).getClerkLimit();
473	        return limit != null && due != null && due.compareTo(limit) > 0 && !roles.isSteward(sheetId, user);
474	    }
475	
476	    /** Refuse a negative amount that does not name a SETTLED claim of the person by number, and a claim of
477	     *  0.00 or more that names one. */
478	    private void refuseCorrection(String sheetId, long personId, BigDecimal amount, String corrects) {
479	        if (amount.signum() >= 0) {
480	            if (corrects != null) {
481	                throw new ClaimCorrectionException("Only a negative amount corrects a claim.");
482	            }
483	            return;
484	        }
485	        if (corrects == null) {
486	            throw new ClaimCorrectionException(
487	                    "A negative amount is a correction: name the number of the settled claim it corrects.");
488	        }
489	        if (!claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
490	            throw new ClaimCorrectionException("A correction must name a settled claim of the same person.");
491	        }
492	    }
493	
494	    /** Refuse a claim dated after its person's retirement date. */
495	    private static void refuseRetired(Person person, LocalDate date) {
496	        if (person.retiredOn(date)) {
497	            throw new PersonRetiredException();
498	        }
499	    }
500	
501	    /** A claim's figure: the due fixed when settled, else the one its last statement bound (not while
502	     *  PENDING), else its live due; none when that is n/a. */
503	    private BigDecimal due(Claim claim, Person person) {
504	        if (claim.getSettledDue() != null) {
505	            return claim.getSettledDue();
506	        }
507	        return claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
508	    }
509	
510	    /** Log the status a claim has just taken: by the user, on the sheet's today, with its due as the
511	     *  screen shows it now. */
512	    private void logStatus(Claim claim, Person person, String user) {
513	        claim.logStatus(user, sheets.today(claim.getSheetId()), shownDue(claim, person));
514	    }
515	
516	    /** A claim's due as the screen shows it: fixed when settled, else its figure (bound or live) with its
517	     *  late charge on top; none when that is n/a. */
518	    private BigDecimal shownDue(Claim claim, Person person) {
519	        if (claim.getSettledDue() != null) {
520	            return claim.getSettledDue();
521	        }
522	        BigDecimal figure = due(claim, person);
523	        return figure == null ? null : charged(claim, figure);
524	    }
525	
526	    /** A claim's figure with its late charge on the sheet's today on top while it is OPEN or PENDING. */
527	    private BigDecimal charged(Claim claim, BigDecimal figure) {
528	        return Rollup.charged(sheetRows.findById(claim.getSheetId()), claim, figure);
529	    }
530	
531	    /** The claim's amount at the rate in force on its date of its person's grade in force then, at least the sheet's floor in force then
532	     *  (a correction has none); none when no rate applies. */
533	    private BigDecimal liveDue(Claim claim, Person person) {
534	        Sheet sheet = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new);
535	        RoundingMode rounding = sheet.rounding(roundingDate(claim));
536	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
537	                .map(rate -> claim.isCorrection() ? due(claim.getAmount(), rate, rounding)
538	                        : sheet.floored(due(claim.getAmount(), rate, rounding), claim.getDate()))
539	                .orElse(null);
540	    }
541	
542	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it corrects. */
543	    private LocalDate roundingDate(Claim claim) {
544	        if (!claim.isCorrection()) {
545	            return claim.getDate();
546	        }
547	        return claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
548	                .map(Claim::getDate).orElse(claim.getDate());
549	    }
550	
551	    /** An amount times a rate, divided by 100, rounded to cents. */
552	    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
553	        return amount.multiply(rate.getRate()).movePointLeft(2).setScale(2, rounding);
554	    }
555	
556	    /** The due a settled claim was fixed at, as its audit line ends: n/a when it has none. */
557	    private static String dueField(Claim claim) {
558	        return " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
559	    }
560	
561	    /** A due as an audit line shows it: n/a when there is none. */
562	    private static String show(BigDecimal due) {
563	        return due == null ? "n/a" : due.toPlainString();
564	    }
565	
566	    /** The amount as the screen shows it (two decimals), the date YYYY-MM-DD. */
567	    private void audit(String event, Claim claim, Person person, String user) {
568	        audit(event, claim, person, user, claim.getNumber(), "");
569	    }
570	
571	    /** A claim with a number (a voided claim keeps its own) follows its date with number=, then any extra fields. */
572	    private void audit(String event, Claim claim, Person person, String user, String number, String extra) {
573	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
574	                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
575	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
576	    }
577	}
